import * as stylex from '@stylexjs/stylex';

// Design tokens — the single file users edit to retheme their app.
// Familiar semantic names (background, foreground, muted, accent, ...).
// Values are the light theme; `themes.ts` overrides them per theme.
//
// Colors use oklch (perceptually uniform; easy to shift lightness/chroma).
// Avoid legacy comma syntax like `rgba(0, 0, 0, 0.5)` — the shadcn CLI's
// transformer mangles comma number lists; `oklch(0% 0 0deg / 50%)` is safe.

export const colors = stylex.defineVars({
  background: 'oklch(1 0 0)',
  foreground: 'oklch(0.145 0 0)',
  card: 'oklch(1 0 0)',
  cardForeground: 'oklch(0.145 0 0)',
  popover: 'oklch(1 0 0)',
  popoverForeground: 'oklch(0.145 0 0)',
  primary: 'oklch(0.205 0 0)',
  primaryForeground: 'oklch(0.985 0 0)',
  secondary: 'oklch(0.97 0 0)',
  secondaryForeground: 'oklch(0.205 0 0)',
  muted: 'oklch(0.97 0 0)',
  mutedForeground: 'oklch(0.556 0 0)',
  accent: 'oklch(0.97 0 0)',
  accentForeground: 'oklch(0.205 0 0)',
  destructive: 'oklch(0.577 0.245 27.325)',
  destructiveForeground: 'oklch(0.985 0 0)',
  border: 'oklch(0.922 0 0)',
  input: 'oklch(0.922 0 0)',
  ring: 'oklch(0.708 0 0)',
  overlay: 'oklch(0% 0 0deg / 50%)',
});

export const radius = stylex.defineVars({
  sm: '0.375rem',
  md: '0.5rem',
  lg: '0.625rem',
  xl: '0.75rem',
  full: '9999px',
});

export const font = stylex.defineVars({
  sans: "ui-sans-serif, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif",
  mono: "ui-monospace, SFMono-Regular, Menlo, Consolas, 'Liberation Mono', monospace",
});

// Shadows stay hex-alpha: the CLI parses shadow shorthands separately and
// mangles oklch() inside them.
export const shadow = stylex.defineVars({
  sm: '0 1px 2px #0000000d',
  md: '0 4px 8px -2px #0000001a',
  lg: '0 10px 20px -5px #00000026',
});

import * as stylex from '@stylexjs/stylex';

// Non-themed scales (compile-time constants — see STYLEX.md). Themable tokens
// (colors, radius, fonts, shadows) live in tokens.stylex.ts as defineVars.

// Spacing scale in 0.25rem (4px) steps; sNN = NN * 0.25rem.
export const space = stylex.defineConsts({
  s05: '0.125rem',
  s1: '0.25rem',
  s15: '0.375rem',
  s2: '0.5rem',
  s25: '0.625rem',
  s3: '0.75rem',
  s4: '1rem',
  s5: '1.25rem',
  s6: '1.5rem',
  s7: '1.75rem',
  s8: '2rem',
  s9: '2.25rem',
  s10: '2.5rem',
  s12: '3rem',
  s16: '4rem',
});

export const fontSize = stylex.defineConsts({
  xs: '0.75rem',
  sm: '0.875rem',
  base: '1rem',
  lg: '1.125rem',
  xl: '1.5rem',
});

export const lineHeight = stylex.defineConsts({
  none: '1',
  tight: '1.3',
  snug: '1.4',
  normal: '1.5',
  // Single-line control text (paired with fontSize.sm, like Tailwind's
  // text-sm 14/20). A 20px line box centers on whole pixels inside our
  // control heights — ratio-based heights land on half pixels and make
  // Base UI's align-item-with-trigger text drift by 1px.
  control: '1.25rem',
});

export const fontWeight = stylex.defineConsts({
  medium: '500',
  semibold: '600',
  bold: '700',
});

export const z = stylex.defineConsts({
  popup: '50',
  toast: '100',
});

export const duration = stylex.defineConsts({
  fast: '150ms',
  // Modal-tier surfaces (dialog, sheet): big enough to read as deliberate,
  // still under the 300ms ceiling for UI motion.
  normal: '200ms',
  // Larger surface moves (drawer, toast stack, navigation menu morph).
  slow: '350ms',
});

// Easing curves. Built-in CSS keywords are too weak for UI motion; these are
// the house curves — never inline a cubic-bezier in component styles.
export const easing = stylex.defineConsts({
  // Enter/exit and state response: fast start, gentle settle.
  out: 'cubic-bezier(0.23, 1, 0.32, 1)',
  // On-screen movement between two resting positions (switch thumb,
  // navigation menu morph).
  inOut: 'cubic-bezier(0.77, 0, 0.175, 1)',
  // iOS-like drawer curve.
  drawer: 'cubic-bezier(0.32, 0.72, 0, 1)',
});

export const stroke = stylex.defineConsts({
  border: '1px',
  focus: '2px',
  // Soft state ring (hover/active halo on slider thumbs etc.), like
  // Tailwind's ring-3.
  halo: '3px',
});

// Container widths for popups, panels, and example layouts.
export const container = stylex.defineConsts({
  xs: '10rem',
  card: '16rem',
  sm: '18rem',
  md: '20rem',
  lg: '24rem',
  xl: '28rem',
  xxl: '32rem',
});

import * as stylex from '@stylexjs/stylex';

import { colors } from './tokens.stylex';

// Apply to <html> (not a wrapper): dialogs/popovers portal to <body> and
// would escape a subtree theme. <html {...stylex.props(darkTheme)}>.
export const darkTheme = stylex.createTheme(colors, {
  background: 'oklch(0.145 0 0)',
  foreground: 'oklch(0.985 0 0)',
  card: 'oklch(0.205 0 0)',
  cardForeground: 'oklch(0.985 0 0)',
  popover: 'oklch(0.205 0 0)',
  popoverForeground: 'oklch(0.985 0 0)',
  primary: 'oklch(0.922 0 0)',
  primaryForeground: 'oklch(0.205 0 0)',
  secondary: 'oklch(0.269 0 0)',
  secondaryForeground: 'oklch(0.985 0 0)',
  muted: 'oklch(0.269 0 0)',
  mutedForeground: 'oklch(0.708 0 0)',
  accent: 'oklch(0.269 0 0)',
  accentForeground: 'oklch(0.985 0 0)',
  destructive: 'oklch(0.704 0.191 22.216)',
  destructiveForeground: 'oklch(0.205 0 0)',
  border: 'oklch(0.269 0 0)',
  input: 'oklch(0.325 0 0)',
  ring: 'oklch(0.556 0 0)',
  overlay: 'oklch(0% 0 0deg / 70%)',
});

// Themes are static by design — StyleX resolves `createTheme` at compile
// time, so add variations by writing more `createTheme` calls here, not by
// computing them at runtime. A theme need not override every token: a partial
// one composes with a full one and the later theme wins per token, e.g.
// `stylex.props(darkTheme, brandTheme)`.
